import {futureIntegrations} from './integrations.mjs';
import {illustration,logo,arrow,doodle} from './illustrations.mjs';
import {money as m,parseCurrency} from './model.mjs';
import {defaultCollaboration,collaborationKey,collaborationTotal,collaborationTransition,loadCollaboration,publicGoal} from './collaboration-model.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(text,route,cls='btn')=>`<a class="${cls}" href="#/${route}">${text}${cls.includes('btn')&&!cls.includes('text')?arrow():''}</a>`;
export function createBrand({getPlan,onSession,announce,rerender}){
 let collaboration;try{collaboration=loadCollaboration(localStorage);}catch{collaboration=defaultCollaboration();}
 let opener=null;
 const avatars=()=>`<span class="avatar-stack" aria-hidden="true"><span class="avatar">A</span>${collaboration.status==='ACCEPTED'?'<span class="avatar rohan">R</span>':''}</span>`;
 const sharedLabel=()=>collaboration.status==='ACCEPTED'?'Aanya + Rohan':collaboration.status==='INVITE_SENT'?'Invite pending':'Only you for now';
 function save(event,payload){try{const next=collaborationTransition(collaboration,event,payload);localStorage.setItem(collaborationKey,JSON.stringify(next));collaboration=next;return true;}catch(e){announce(e.message==='This permission allows viewing only.'?e.message:"We couldn't save that change. Your previous shared goal is intact.");return false;}}
 function marketingHeader(){return `<header class="header marketing-header"><a class="brand" href="#/" aria-label="ELSE home">${logo()}</a><nav class="marketing-links" aria-label="Landing sections"><button data-scroll="how-it-works">How it works</button><button data-scroll="why-else">Why ELSE</button><button data-scroll="shared-goals">Shared goals</button></nav><div class="actions">${link('Log in','login','text-btn')}${link('Try the demo','home','btn')}</div></header>`;}
 function landing(){return `${marketingHeader()}<main id="main" tabindex="-1" class="landing-page"><section class="else-hero"><div class="hero-copy"><div class="eyebrow">See the rest of the decision.</div><h1>Your balance tells you <span>what you have.</span><br>ELSE shows you <span class="headline-last">what it changes.</span></h1><p>Explore how a purchase could affect your commitments, goals and breathing room before you decide.</p><div class="actions">${link('Try the demo','home')}${link('Create account','signup','btn secondary')}</div><p class="hero-note">A portfolio concept. No account needed to explore.</p></div><div class="financial-story"><div class="story-top">ONE PURCHASE. A FEW RIPPLES.</div><div class="story-object coffee">${illustration('coffee')}</div><div class="story-object phone">${illustration('phone')}<span>New phone · ₹12,000</span></div><div class="story-number"><span>Flexible before goals</span><strong class="num">₹16,100</strong>${doodle()}<span class="story-after">After the hypothetical purchase <b class="num">₹4,100</b></span></div><div class="story-object suitcase">${illustration('suitcase')}</div><div class="story-consequences"><div><small>Preferred buffer</small><strong>₹2,900 gap</strong></div><div><small>Optional Goa plan</small><strong>Nov 08 → Nov 20</strong></div></div><span class="story-footnote">A scenario, not a recommendation.</span></div></section><section class="balance-story reveal" id="why-else"><div><div class="eyebrow">There’s more behind the balance</div><h2>₹42,800 isn’t<br>the whole story.</h2><p>Balances show money. They don’t show everything that money is already doing.</p></div><div class="balance-separation"><div><span>Available now</span><strong class="num">₹42,800</strong></div><div class="balance-parts"><div><span class="dot"></span><strong class="num">₹26,700</strong><small>Already spoken for</small></div><div><span class="dot light"></span><strong class="num">₹16,100</strong><small>Flexible before goals</small></div></div><p>Goals and your preferred buffer are separate planning preferences.</p></div></section><section class="signature-section reveal"><div class="signature-copy"><div class="eyebrow">Meet the what-if</div><h2>What else would<br>₹12,000 change?</h2>${illustration('person','signature-person')}<p>Your essentials stay protected. Your breathing room and a goal plan come into view.</p>${link('Explore this scenario','purchase')}</div><div class="signature-data"><div class="signature-row"><span>Essentials</span><strong class="tag">✓ Protected</strong></div><div class="signature-row"><span>Flexible before goals</span><strong class="num">₹16,100 → ₹4,100</strong></div><div class="signature-row"><span>Preferred ₹7,000 buffer</span><strong class="num">₹2,900 gap</strong></div><div class="signature-row"><span>Optional Goa contribution</span><strong class="num">₹8,000 → ₹5,100</strong></div><div class="signature-row"><span>Illustrative completion</span><strong>Nov 08 → Nov 20</strong></div><p class="explanation">Lowering a planned contribution reallocates money within the plan; it does not create cash or close the ₹2,900 cash buffer gap.</p></div></section><section class="how-section" id="how-it-works"><div class="eyebrow">How ELSE works</div><h2>A question. A little context.<br>Your decision.</h2><div class="how-grid"><article class="reveal">${illustration('phone')}<span class="eyebrow">01 / Thinking about something?</span><h3>Enter the amount.</h3><p>A phone, a coffee, a plan. Start with what’s on your mind.</p></article><article class="reveal">${illustration('ripple')}<span class="eyebrow">02 / See what else changes</span><h3>See the ripple.</h3><p>Understand commitments, flexible money, your buffer and goals.</p></article><article class="reveal">${illustration('paths')}<span class="eyebrow">03 / You decide</span><h3>Keep the choice yours.</h3><p>Adjust the plan, keep it, or explore another amount.</p></article></div></section><section class="shared-story reveal" id="shared-goals"><div class="shared-story-art">${illustration('shared')}<div>${avatars()}<span>Aanya + Rohan</span></div><strong>Goa · ₹18,000 / ₹30,000</strong></div><div><div class="eyebrow">A little togetherness</div><h2>Some goals aren’t<br>yours alone.</h2><p>Plan shared goals together without exposing everything else about your money.</p><p class="muted">Only the goal is shared. Your balance, transactions and other goals stay private.</p>${link('See shared goals','goals/goa','btn secondary')}</div></section><section class="trust-section reveal"><h2>Your decision stays yours.</h2><div class="trust-grid"><article><span class="eyebrow">No judgment</span><p>ELSE shows consequences, not good or bad spending.</p></article><article><span class="eyebrow">No automatic changes</span><p>Plans change only when you apply them.</p></article><article><span class="eyebrow">Private by default</span><p>Collaborators see only the goal you choose to share.</p></article></div></section><section class="final-cta reveal"><div><div class="eyebrow">A little perspective goes a long way</div><h2>Before you spend,<br>see what else.</h2><div class="actions">${link('Try the demo','home')}${link('Create account','signup','btn secondary')}</div></div>${illustration('wallet')}</section></main>${futureIntegrations()}<footer class="landing-footer"><a class="brand" href="#/">${logo()}</a><div><button data-scroll="how-it-works">How it works</button>${link('Product','home','text-btn')}${link('Shared goals','goals/goa','text-btn')}</div><span class="creator-credit">A product exploration by <strong>Mitali Giri</strong><small>Local demo · No payments</small></span></footer>`;}
 function auth(mode){const signup=mode==='signup';return `${marketingHeader()}<main id="main" tabindex="-1" class="auth-layout fade"><aside class="auth-story"><span class="eyebrow">See what else.</span><h2>Money has plans.<br>See all of them.</h2>${illustration('person','auth-person')}<div class="auth-objects">${illustration('coffee')}${illustration('receipt')}${illustration('suitcase')}</div><p>A little clarity, without the judgment.</p></aside><section class="auth-form"><div class="eyebrow">${signup?'A clearer starting point':'Your month awaits'}</div><h1>${signup?'Let’s see the<br>whole picture.':'Welcome back.'}</h1><p>This portfolio prototype uses demo/local data.</p><form id="${signup?'signup':'login'}">${signup?'<label for="name">Name</label><input id="name" name="name" autocomplete="given-name" value="Aanya" required>':''}<label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" placeholder="aanya@example.com" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="8" required aria-describedby="password-help"><small id="password-help" class="muted">Mock sign-in. Use sample details; passwords are not stored.</small>${signup?'':'<button type="button" class="text-btn forgot" data-brand="forgot">Forgot password?</button>'}<button class="btn" type="submit">${signup?'Create account':'Log in'}${arrow()}</button></form><p class="auth-switch">${signup?'Already have an account?':'Don’t have an account?'} ${link(signup?'Log in':'Create one',signup?'login':'signup','text-btn')}</p>${link('Explore demo','home','text-btn')}</section></main>`;}
 function badge(){return `<div class="shared-badge">${avatars()}<span>${sharedLabel()}<small>${collaboration.status==='ACCEPTED'?'Shared goal':'Goal-level sharing only'}</small></span><button class="text-btn" type="button" data-brand="manage">Manage</button></div>`;}
 function activity(snapshot){return `<section class="shared-activity"><div class="section-title"><h2>Shared goal activity</h2><span class="muted">Goal events only</span></div><ul>${snapshot.planChange?`<li><span>Oct 03</span><div>Aanya adjusted the October goal plan<strong>${m(snapshot.planChange.before)} → ${m(snapshot.planChange.after)}</strong></div></li>`:''}${snapshot.events.map(e=>`<li><span>${esc(e.date)}</span><div>${esc(e.text)}<strong>${m(e.amount)}</strong></div></li>`).join('')}<li><span>Oct 02</span><div>Rohan added ₹2,000<small>Included in the ₹6,000 saved contribution</small></div></li><li><span>Sep 28</span><div>Rohan joined the goal</div></li></ul></section>`;}
 function contributions(s){return `<div class="shared-contributions">${s.contributions.map(c=>`<div><span class="avatar ${c.name==='Rohan'?'rohan':''}" aria-hidden="true">${c.name[0]}</span><span>${c.name}<small>Saved contribution</small></span><strong class="num">${m(c.saved)}</strong></div>`).join('')}</div>`;}
 function detailExtras(){const s=publicGoal(getPlan(),collaboration);return `<section class="shared-goal-section"><div class="shared-note"><div><h2>Shared note</h2><p>${esc(s.note)||'No note yet.'}</p></div><button type="button" class="text-btn" data-brand="owner-note">Edit note</button></div>${activity(s)}<div class="actions"><button type="button" class="btn secondary" data-brand="manage">Manage collaborators</button>${collaboration.status==='ACCEPTED'?link('Preview as collaborator','shared/goa','btn secondary'):''}</div><p class="data-note">Only this goal is shared. Your salary, balance, commitments, transactions, emergency fund and personal scenarios stay private.</p></section>`;}
 function collaboratorPage(s){const accepted=s.status==='ACCEPTED';return `<header class="header"><a class="brand" href="#/" aria-label="ELSE landing">${logo()}</a><span class="preview-tag">COLLABORATOR DEMO</span></header><main id="main" tabindex="-1" class="collaborator-page fade"><div class="back">${link('Return to owner demo','goals/goa','text-btn')}</div>${accepted?`<div class="page-heading"><div><div class="eyebrow">Shared with Rohan · Only this goal</div><h1>Goa, together.</h1></div><span class="tag">${s.permission==='view'?'Can view':'Can contribute'}</span></div><div class="collaborator-summary">${illustration('shared')}<div><div class="detail-amount num">${m(s.saved)} <small>of ${m(s.target)}</small></div><div class="progress" role="img" aria-label="${Math.round(s.saved/s.target*100)}% saved"><span style="width:${Math.min(100,s.saved/s.target*100)}%"></span></div><p>${Math.round(s.saved/s.target*100)}% saved · ${m(Math.max(0,s.target-s.saved))} remaining</p></div></div>${contributions(s)}<dl class="detail-facts"><div><dt>Shared October plan</dt><dd>${m(s.plannedContribution)}</dd></div><div><dt>Illustrative completion</dt><dd>${esc(s.estimatedCompletion)}</dd></div></dl><div class="shared-note"><div><h2>Shared note</h2><p>${esc(s.note)}</p></div>${s.permission==='contribute'?'<button class="text-btn" type="button" data-brand="collaborator-note">Edit note</button>':'<span class="muted">View only</span>'}</div>${s.permission==='contribute'?'<button class="btn secondary" type="button" data-brand="record">Record demo contribution</button>':''}${activity(s)}<div class="privacy-note">This view contains the shared goal only. It does not include the owner’s private financial activity.</div>`:`<div class="empty-state">${illustration('shared')}<h1>${s.status==='INVITE_SENT'?'The invite is still pending.':'This goal is no longer shared.'}</h1><p>Return to the owner demo to manage goal access.</p></div>`}</main>`;}
 function manageContent(){return `<div class="modal-eyebrow">ONLY THIS GOAL IS SHARED</div><h2 id="dialog-title">Who else is planning this?</h2><p class="muted">Collaborators see Goa, not your personal financial activity.</p><div class="collaborator-row"><span class="avatar">A</span><div><strong>Aanya</strong><small>Goal owner</small></div><span class="tag">Owner</span></div>${collaboration.status!=='REMOVED'?`<div class="collaborator-row"><span class="avatar rohan">R</span><div><strong>Rohan</strong><small>${esc(collaboration.email)}</small></div><span class="tag">${collaboration.status==='INVITE_SENT'?'Invite pending':'Collaborator'}</span></div>${collaboration.status==='INVITE_SENT'?'<button class="btn secondary" type="button" data-brand="accept">Accept demo invite</button>':`<label for="permission">Rohan’s permission</label><select id="permission"><option value="contribute" ${collaboration.permission==='contribute'?'selected':''}>Can contribute · edit notes and record demo contributions</option><option value="view" ${collaboration.permission==='view'?'selected':''}>Can view · progress, timeline and activity</option></select><button class="text-btn" type="button" data-brand="save-permission">Save permission</button>`}<button type="button" class="text-btn remove" data-brand="remove">${collaboration.status==='INVITE_SENT'?'Withdraw invite':'Remove collaborator'}</button>`:`<div class="collaboration-empty">${illustration('shared')}<p>Some goals are easier to plan together.</p></div>`}<div class="modal-actions"><button type="button" class="btn" data-brand="invite">${collaboration.status==='REMOVED'?'Invite someone':'Invite / review sharing'}${arrow()}</button><button type="button" class="btn secondary" data-brand="close">Done</button></div>`;}
 function openDialog(content,target){opener=target?.isConnected?target:document.activeElement?.closest('#else-dialog')?document.querySelector('[data-brand=manage]'):document.activeElement;document.querySelector('#else-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='else-dialog';dialog.setAttribute('aria-labelledby','dialog-title');dialog.innerHTML=`<button type="button" class="dialog-close" aria-label="Close dialog" data-brand="close">×</button>${content}`;document.body.append(dialog);dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const controls=[...dialog.querySelectorAll('button,a[href],input,select,textarea')].filter(el=>!el.disabled&&el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}});dialog.addEventListener('close',()=>{dialog.remove();opener?.focus();});dialog.showModal();}
 function close(){document.querySelector('#else-dialog')?.close();}
 function inviteContent(){return `<h2 id="dialog-title">Share this goal.</h2><p>They’ll only see Goa, not your personal financial activity.</p><form id="invite-form"><label for="invite-email">Email</label><input type="email" id="invite-email" value="rohan@example.com" required><label for="invite-permission">Permission</label><select id="invite-permission"><option value="contribute">Can contribute</option><option value="view">Can view</option></select><p class="muted">This is a local demo invitation. No email is sent.</p><div class="modal-actions"><button class="btn" type="submit">Send invite${arrow()}</button><button class="btn secondary" type="button" data-brand="close">Cancel</button></div></form>`;}
 function afterRender(route){if(route===''){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target);}}, {threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}if(route==='setup'){document.querySelector('.form-panel')?.classList.add('onboarding-panel');} }
 function click(e){const el=e.target.closest('[data-brand],[data-scroll]');if(!el)return false;if(el.dataset.scroll){const dest=el.dataset.scroll;if(!document.querySelector('#'+dest)){location.hash='/';requestAnimationFrame(()=>document.querySelector('#'+dest)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));}else document.querySelector('#'+dest).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return true;}
 const action=el.dataset.brand;if(action==='close'){close();return true;}if(action==='manage'){openDialog(manageContent(),el);return true;}if(action==='invite'){openDialog(inviteContent(),opener);return true;}if(action==='accept'||action==='remove'){if(save(action==='accept'?'ACCEPTED':'REMOVED')){close();rerender();announce(action==='accept'?'Demo invite accepted. Only Goa is shared.':'Collaborator removed. Saved contributions remain in the goal.');}return true;}if(action==='save-permission'){if(save('PERMISSION',{permission:document.querySelector('#permission').value})){close();rerender();announce('Goal permission updated.');}return true;}if(action==='forgot'){openDialog(`<h2 id="dialog-title">A shortcut back to the demo.</h2><p>This prototype doesn’t send password-reset emails. Use any sample email and an 8-character sample password, or explore without signing in.</p>${link('Explore demo','home','btn')}<button type="button" class="text-btn" data-brand="close">Close</button>`,el);return true;}
 if(action==='owner-note'||action==='collaborator-note'){if(action==='collaborator-note'&&(collaboration.permission!=='contribute'||collaboration.status!=='ACCEPTED')){announce('This permission allows viewing only.');return true;}openDialog(`<h2 id="dialog-title">A note for this goal.</h2><form id="shared-note-form" data-actor="${action==='owner-note'?'aanya':'rohan'}"><label for="shared-note">Shared note</label><textarea id="shared-note" maxlength="240" rows="4">${esc(collaboration.note)}</textarea><p class="muted">Visible to everyone sharing Goa. Keep private account details out of shared notes.</p><div class="modal-actions"><button class="btn" type="submit">Save note</button><button class="btn secondary" data-brand="close" type="button">Cancel</button></div></form>`,el);return true;}
 if(action==='record'){if(collaboration.permission!=='contribute'||collaboration.status!=='ACCEPTED'){announce('Contribution permission is required.');return true;}openDialog(`<h2 id="dialog-title">Record a demo contribution.</h2><form id="record-form"><label for="record-amount">Amount added by Rohan</label><div class="input-money"><span>₹</span><input id="record-amount" type="text" inputmode="numeric" value="2000" required aria-describedby="record-error"></div><p id="record-error" class="error" role="alert"></p><p class="muted">Updates this goal’s demo record only. No money is transferred and the owner’s account balance is unchanged.</p><div class="modal-actions"><button class="btn" type="submit">Record contribution</button><button class="btn secondary" type="button" data-brand="close">Cancel</button></div></form>`,el);return true;}return false;
 }
 function submit(e){const form=e.target;if(['login','signup'].includes(form.id)){e.preventDefault();try{localStorage.setItem('else-mock-session',JSON.stringify({mode:'mock',name:form.id==='signup'?(form.querySelector('#name').value.trim()||'Aanya'):(localStorage.getItem('else-profile-name')||'Aanya')}));onSession(form.id==='signup'?'setup':'home');}catch{announce("We couldn't save this local session. You can still explore the demo.");}return true;}if(form.id==='invite-form'){e.preventDefault();if(save('INVITE_SENT',{email:document.querySelector('#invite-email').value,permission:document.querySelector('#invite-permission').value})){close();rerender();openDialog(manageContent(),opener);announce('Invite pending. No email was sent.');}return true;}if(form.id==='shared-note-form'){e.preventDefault();if(save('NOTE',{actor:form.dataset.actor,note:document.querySelector('#shared-note').value})){close();rerender();announce('Shared note updated.');}return true;}if(form.id==='record-form'){e.preventDefault();const input=document.querySelector('#record-amount');const amount=parseCurrency(input.value);if(!Number.isInteger(amount)||amount<=0||amount>12000-collaboration.rohanExtra){document.querySelector('#record-error').textContent='Enter a whole-rupee amount from ₹1 to '+m(12000-collaboration.rohanExtra)+'.';input.setAttribute('aria-invalid','true');input.focus();return true;}if(save('CONTRIBUTION',{amount})){close();rerender();announce('Demo contribution recorded. No money moved.');}return true;}return false;}
 return {landing,auth,marketingHeader,badge,detailExtras,contributions,collaboratorPage,afterRender,click,submit,publicSnapshot:()=>publicGoal(getPlan(),collaboration),saved:()=>collaborationTotal(collaboration)};
}
